if (!forDistanceQueries) {
    // If tree is not optimized for distance queries, accelerate it
    tree.accelerate_distance_queries();
}

CGAL::Point_3 query_point(p.x(), p.y(), p.z());
CGAL::Point_3 nearest_point;
bool found = tree.closest_point(query_point, nearest_point);

if (!found) {
    // If no closest point found (shouldn't happen for valid meshes),
    // return the first vertex as fallback
    if (!triangles.empty()) {
        const auto& first_triangle = triangles.front();
        return Point3d(first_triangle[0].x(), first_triangle[0].y(), first_triangle[0].z());
    }
    return Point3d(0, 0, 0); // Return origin as last resort
}

return Point3d(nearest_point.x(), nearest_point.y(), nearest_point.z());

